sources.python/urgent.py:
from jobs import initial


def urgent(jobs):
    best = initial(jobs)
    for candidate in jobs:
        if candidate["severity"] > best["severity"]:
            best = candidate
    return best["id"]

sources.python/nearby.py:
from jobs import initial


def nearby(jobs):
    best = initial(jobs)
    for candidate in jobs:
        if candidate["travel"] < best["travel"]:
            best = candidate
    return best["id"]

